import itertools

# S = {0, 1, 2}
S = [0, 1, 2]

# 1. Calculate P1 = {f - g | f, g in S}
P1 = set()
for f in S:
    for g in S:
        P1.add(f - g)
P1 = sorted(list(P1))

print(f"P1: {P1}")

# 2. Calculate P2 = {r * p * q | p, q in P1}. We will use r=1 initially for inspection.
# Since r is unknown, we calculate the set of products pq first.
Products_PQ = set()
for p in P1:
    for q in P1:
        Products_PQ.add(p * q)

# We will use r=1 to check containment in P3
r_test = 1
P2_test = {r_test * val for val in Products_PQ}
print(f"P2 (for r=1): {sorted(list(P2_test))}")

# 3. Calculate P3 = {x^2 + y^2 - z^2 - w^2 | x, y, z, w in P1}
P3 = set()
P1_sq = [x**2 for x in P1]

# Iterate over all combinations of four elements from P1_sq
for x2 in P1_sq:
    for y2 in P1_sq:
        for z2 in P1_sq:
            for w2 in P1_sq:
                P3.add(x2 + y2 - z2 - w2)

P3 = sorted(list(P3))
print(f"P3: {P3}")
